import React from 'react';
import { ArrowLeftIcon } from './Icons';

export const Navbar = ({ 
  showNav = false, 
  onBack = null, 
  showBackButton = false,
  currentPage = 'landing',
  onNavigate = null 
}) => {
  if (!showNav) return null;

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-gray-900/95 backdrop-blur-lg border-b border-gray-800">
      <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">
        
        {/* Left: Logo + Back Button */}
        <div className="flex items-center gap-4">
          {showBackButton && onBack && (
            <button
              onClick={onBack}
              className="flex items-center gap-2 text-gray-300 hover:text-white transition-colors"
            >
              <ArrowLeftIcon className="w-5 h-5" />
              <span>Back</span>
            </button>
          )}
          
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => onNavigate && onNavigate('landing')}>
            <span className="text-2xl">🎓</span>
            <span className="text-xl font-bold text-white">Saarthi</span>
          </div>
        </div>
        
        {/* Right: Navigation Links */}
        <div className="flex items-center gap-6 text-sm">
          <button
            onClick={() => onNavigate && onNavigate('landing')}
            className={`transition-colors ${
              currentPage === 'landing' ? 'text-blue-400 font-semibold' : 'text-gray-300 hover:text-white'
            }`}
          >
            Home
          </button>
          <button
            onClick={() => onNavigate && onNavigate('companions')}
            className={`transition-colors ${
              currentPage === 'companions' ? 'text-blue-400 font-semibold' : 'text-gray-300 hover:text-white'
            }`}
          >
            AI Tutors
          </button>
          <button
            onClick={() => onNavigate && onNavigate('room')}
            className={`transition-colors ${
              currentPage === 'room' ? 'text-blue-400 font-semibold' : 'text-gray-300 hover:text-white'
            }`}
          >
            Room
          </button>
        </div>
      </div>
    </nav>
  );
};
